    if isinstance(value, ast.Num):
        result = value.n
    elif isinstance(value, ast.Str):
        result = value.s
    elif isinstance(value, ast.NameConstant):
        result = value.value
    elif isinstance(value, ast.UnaryOp):
        operand = _get_ast_value(value.operand)
        if isinstance(value.op, ast.USub):
            result = -operand
        elif isinstance(value.op, ast.UAdd):
            result = +operand
        else:
            raise ValueError
    else:
        raise ValueError
    return result

